qss.dark-comfortable:
/* ── base ─────────────────────────────────────────────────────────────── */
QWidget {
    font-family: Segoe UI, Inter, 'Helvetica Neue', Arial, sans-serif;
    font-size: 13px;
    color: #F1E9DA;
    background-color: #151615;
}
QWidget:disabled { color: #6C6555; }
QLabel { background: transparent; }
QLabel[role="subtitle"] { color: #C8BCA6; }
QLabel[role="muted"] { color: #9E947F; }
QLabel#hrEmptyState, QLabel[role="empty"] { color: #9E947F; }

/* ── buttons ──────────────────────────────────────────────────────── */

QPushButton[variant="primary"] {
    background-color: #5AA377; color: #182420;
    border: 1px solid #5AA377;
    border-radius: 6px;
    min-height: 32px;
    padding: 0 14px;
    font-weight: 600;
}
QPushButton[variant="primary"]:hover { background-color: #6BB588; border-color: #6BB588; }
QPushButton[variant="primary"]:pressed { background-color: #529970; border-color: #529970; }
QPushButton[variant="primary"]:disabled {
    background-color: #1C2622; color: #6C6555;
    border-color: #33403A;
}

QPushButton[variant="secondary"] {
    background-color: #252825; color: #F1E9DA;
    border: 1px solid #3A4A42;
    border-radius: 6px;
    min-height: 32px;
    padding: 0 14px;
    font-weight: 600;
}
QPushButton[variant="secondary"]:hover { background-color: #1B1D1B; border-color: #1B1D1B; }
QPushButton[variant="secondary"]:pressed { background-color: #3A4A42; border-color: #3A4A42; }
QPushButton[variant="secondary"]:disabled {
    background-color: #1C2622; color: #6C6555;
    border-color: #33403A;
}

QPushButton[variant="success"] {
    background-color: #5CB878; color: #182420;
    border: 1px solid #5CB878;
    border-radius: 6px;
    min-height: 32px;
    padding: 0 14px;
    font-weight: 600;
}
QPushButton[variant="success"]:hover { background-color: #5CB878; border-color: #5CB878; }
QPushButton[variant="success"]:pressed { background-color: #5CB878; border-color: #5CB878; }
QPushButton[variant="success"]:disabled {
    background-color: #1C2622; color: #6C6555;
    border-color: #33403A;
}

QPushButton[variant="warning"] {
    background-color: #E0A45A; color: #182420;
    border: 1px solid #E0A45A;
    border-radius: 6px;
    min-height: 32px;
    padding: 0 14px;
    font-weight: 600;
}
QPushButton[variant="warning"]:hover { background-color: #E0A45A; border-color: #E0A45A; }
QPushButton[variant="warning"]:pressed { background-color: #E0A45A; border-color: #E0A45A; }
QPushButton[variant="warning"]:disabled {
    background-color: #1C2622; color: #6C6555;
    border-color: #33403A;
}

QPushButton[variant="danger"] {
    background-color: #E0716D; color: #182420;
    border: 1px solid #E0716D;
    border-radius: 6px;
    min-height: 32px;
    padding: 0 14px;
    font-weight: 600;
}
QPushButton[variant="danger"]:hover { background-color: #EA8783; border-color: #EA8783; }
QPushButton[variant="danger"]:pressed { background-color: #D96965; border-color: #D96965; }
QPushButton[variant="danger"]:disabled {
    background-color: #1C2622; color: #6C6555;
    border-color: #33403A;
}

QPushButton[variant="accent"] {
    background-color: #D8B879; color: #F1E9DA;
    border: 1px solid #D8B879;
    border-radius: 6px;
    min-height: 32px;
    padding: 0 14px;
    font-weight: 600;
}
QPushButton[variant="accent"]:hover { background-color: #E4C88E; border-color: #E4C88E; }
QPushButton[variant="accent"]:pressed { background-color: #C4A464; border-color: #C4A464; }
QPushButton[variant="accent"]:disabled {
    background-color: #1C2622; color: #6C6555;
    border-color: #33403A;
}

QPushButton[variant="outline"] {
    background-color: transparent; color: #5AA377;
    border: 1px solid #3B5A49;
    border-radius: 6px; min-height: 32px;
    padding: 0 14px;
    font-weight: 500;
}
QPushButton[variant="outline"]:hover { background-color: #1B2C24; }
QPushButton[variant="ghost"] {
    background-color: transparent; color: #5AA377;
    border: none; min-height: 32px;
    padding: 0 10px;
}
QPushButton[variant="ghost"]:hover { background-color: #1B2C24; }
QPushButton:focus { outline: none; border: 2px solid #D8B879; }

/* ── inputs ───────────────────────────────────────────────────────────── */
QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QDateEdit, QTimeEdit,
QDateTimeEdit, QPlainTextEdit, QTextEdit {
    background-color: #252825;
    color: #F1E9DA;
    border: 1px solid #3A4A42;
    border-radius: 4px;
    min-height: 24px;
    padding: 6px 10px;
    selection-background-color: #233A2E;
    selection-color: #F1E9DA;
}
QLineEdit:focus, QComboBox:focus, QSpinBox:focus, QDoubleSpinBox:focus,
QDateEdit:focus, QTimeEdit:focus, QDateTimeEdit:focus, QPlainTextEdit:focus,
QTextEdit:focus { border: 2px solid #D8B879; }
QLineEdit:disabled, QComboBox:disabled {
    background-color: #1C2622; color: #6C6555;
    border-color: #33403A;
}
QLineEdit[state="error"], QComboBox[state="error"] { border-color: #E0716D; }
QLineEdit[state="warning"] { border-color: #E0A45A; }
QLineEdit[readOnly="true"] { background-color: #1B1D1B; color: #C8BCA6; }
QComboBox::drop-down { border: none; width: 20px; }

/* ── tables ───────────────────────────────────────────────────────────── */
QTableWidget#standardTable, QTableView#standardTable {
    background-color: #252825;
    alternate-background-color: #1B1D1B;
    gridline-color: #2A3831;
    border: 1px solid #3A4A42;
    border-radius: 6px;
    selection-background-color: #233A2E;
    selection-color: #F1E9DA;
}
QTableWidget#standardTable::item { padding: 4px 8px; min-height: 32px; }
QHeaderView::section {
    background-color: #1B1D1B;
    color: #C8BCA6;
    padding: 6px 8px;
    border: none;
    border-bottom: 1px solid #3A4A42;
    min-height: 20px;
    font-weight: 600;
}

/* ── cards ────────────────────────────────────────────────────────── */
QFrame#standardCard {
    background-color: #252825;
    border: 1px solid #3A4A42;
    border-radius: 10px;
}
QFrame[cardVariant="section"] {
    background-color: #252825;
    border: 1px solid #3A4A42;
    border-radius: 10px;
}
QFrame[cardVariant="summary"] {
    background-color: #484A48;
    border: 1px solid #3A4A42;
    border-radius: 10px;
}
QFrame[cardVariant="info"] {
    background-color: #152628;
    border: 1px solid #356068;
    border-radius: 10px;
}
QFrame[cardVariant="alert"] {
    background-color: #2C2214;
    border: 1px solid #6B5330;
    border-radius: 10px;
}
QFrame[cardVariant="danger"] {
    background-color: #2C1917;
    border: 1px solid #6B3936;
    border-radius: 10px;
}
QFrame[cardVariant="chart"] {
    background-color: #252825;
    border: 1px solid #3A4A42;
    border-radius: 10px;
}

/* ── kpi ──────────────────────────────────────────────────────────────── */
QFrame#kpiCard {
    background-color: #252825;
    border: 1px solid #3A4A42;
    border-radius: 10px;
}
QLabel#kpiTitle { color: #9E947F; font-size: 11px;
    font-weight: 600; }
QLabel#kpiValue { color: #F1E9DA; font-size: 24px;
    font-weight: 700; }
QLabel#kpiSubtitle { color: #9E947F; font-size: 11px; }
QFrame#kpiCard[variant="primary"] { border-left: 4px solid #5AA377; }
QFrame#kpiCard[variant="success"] { border-left: 4px solid #5CB878; }
QFrame#kpiCard[variant="warning"] { border-left: 4px solid #E0A45A; }
QFrame#kpiCard[variant="danger"] { border-left: 4px solid #E0716D; }
QFrame#kpiCard[variant="info"] { border-left: 4px solid #5FB2C0; }
QFrame#kpiCard[variant="accent"] { border-left: 4px solid #D8B879; }
QFrame#kpiCard[variant="neutral"] { border-left: 4px solid #788D80; }

/* ── page header ──────────────────────────────────────────────────────── */
QFrame#pageHeader { background: transparent; border-bottom: 1px solid #2A3831; }
QLabel#pageHeaderTitle { color: #F1E9DA; font-size: 18px;
    font-weight: 700; }
QLabel#pageHeaderSubtitle { color: #C8BCA6; font-size: 13px; }

/* ── sidebar / nav ────────────────────────────────────────────────────── */
QListWidget#sideNav, QListWidget#financeNav, QListWidget#hrNav, QListWidget[role="nav"] {
    background-color: #1B1D1B;
    border: none;
    border-right: 1px solid #3A4A42;
    outline: none;
}
QListWidget#sideNav::item, QListWidget#financeNav::item, QListWidget#hrNav::item,
QListWidget[role="nav"]::item {
    padding: 8px 12px; color: #C8BCA6; border-radius: 4px;
}
QListWidget#sideNav::item:selected, QListWidget#financeNav::item:selected, QListWidget#hrNav::item:selected,
QListWidget[role="nav"]::item:selected {
    background-color: #1B2C24; color: #5AA377;
    border-left: 3px solid #5AA377;
}

/* ── status badges ────────────────────────────────────────────────── */
QLabel#statusBadge[variant="neutral"] { background-color: #1B1D1B; color: #C8BCA6; border: 1px solid #3A4A42; border-radius: 999px; padding: 2px 10px; }
QLabel#statusBadge[variant="info"] { background-color: #152628; color: #5FB2C0; border: 1px solid #356068; border-radius: 999px; padding: 2px 10px; }
QLabel#statusBadge[variant="success"] { background-color: #17281D; color: #5CB878; border: 1px solid #3E6B4E; border-radius: 999px; padding: 2px 10px; }
QLabel#statusBadge[variant="warning"] { background-color: #2C2214; color: #E0A45A; border: 1px solid #6B5330; border-radius: 999px; padding: 2px 10px; }
QLabel#statusBadge[variant="danger"] { background-color: #2C1917; color: #E0716D; border: 1px solid #6B3936; border-radius: 999px; padding: 2px 10px; }
QLabel#statusBadge[variant="accent"] { background-color: #2C2618; color: #E1C48A; border: 1px solid #D8B879; border-radius: 999px; padding: 2px 10px; }

/* ── tooltip ──────────────────────────────────────────────────────────── */
QToolTip {
    background-color: #0B100D;
    color: #F1E9DA;
    border: 1px solid #788D80;
    border-radius: 4px;
    padding: 6px 8px;
}

/* ── dialogs ──────────────────────────────────────────────────────────── */
QDialog#standardDialog { background-color: #151615; }
QDialog#standardDialog QLabel[role="dialogTitle"] {
    font-size: 15px; font-weight: 600;
    color: #F1E9DA;
}

/* ── forms / specialized inputs ───────────────────────────────────────── */
QLabel#formFieldLabel { color: #C8BCA6; font-weight: 500; }
QLabel#formFieldHelper { color: #9E947F; font-size: 11px; }
QLabel#formFieldError, QLabel[state="error"] {
    color: #E0716D; font-size: 11px;
}
QLineEdit#filePathField[readOnly="true"] {
    background-color: #1B1D1B; color: #C8BCA6;
}
QListWidget#entitySearchResults {
    background-color: #252825; border: 1px solid #3A4A42;
    border-radius: 4px;
}
QListWidget#entitySearchResults::item { padding: 6px 8px; }
QListWidget#entitySearchResults::item:selected {
    background-color: #233A2E; color: #F1E9DA;
}

QPushButton, QToolButton {
    background: #252825; color: #F1E9DA;
    border: 1px solid #3A4A42; border-radius: 6px;
    min-height: 40px; padding: 0 10px;
}
QPushButton[variant], QToolButton[variant] { min-height: 40px; }
QDialog#virtualKeyboard QPushButton {
    min-height: 50px;
    min-width: 26px;
}
QPushButton:hover, QToolButton:hover { background: #1B1D1B; }
QPushButton:pressed, QToolButton:pressed { background: #233A2E; }
QPushButton[variant="ghost"], QPushButton[variant="icon"] {
    background: transparent; border: 1px solid transparent; border-radius: 6px;
}
QPushButton[variant="ghost"]:hover, QPushButton[variant="icon"]:hover { background: #1B2C24; }
QPushButton[variant="ghost"]:pressed, QPushButton[variant="icon"]:pressed { background: #233A2E; }
QPushButton[iconOnly="true"] {
    min-width: 40px;
    min-height: 40px; padding: 0;
}
QPushButton:disabled, QToolButton:disabled, QPushButton[variant="ghost"]:disabled,
QPushButton[variant="icon"]:disabled {
    color: #6C6555; background: #1C2622; border-color: #33403A;
}
QPushButton:focus, QPushButton[variant]:focus, QToolButton:focus {
    border: 2px solid #D8B879;
}
QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QDateEdit, QTimeEdit, QDateTimeEdit {
    min-height: 28px;
}
QAbstractSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #6C6555; background: #1C2622; border-color: #33403A;
}
QAbstractSpinBox[state="error"], QTextEdit[state="error"], QPlainTextEdit[state="error"] {
    border: 2px solid #E0716D;
}
QCheckBox, QRadioButton { min-height: 42px; spacing: 8px; }
QCheckBox:focus, QRadioButton:focus { border: 2px solid #D8B879; }
QTabWidget::pane { border: 1px solid #3A4A42; background: #252825; }
QTabBar::tab {
    min-height: 40px; padding: 0 16px;
    color: #C8BCA6; background: #1B1D1B; border: 1px solid #3A4A42;
}
QTabBar::tab:selected { color: #5AA377; background: #252825; border-bottom: 3px solid #5AA377; }
QTabBar::tab:hover { background: #1B2C24; }
QTabBar::tab:disabled { color: #6C6555; }
QMenu { background: #484A48; border: 1px solid #3A4A42; padding: 4px; }
QMenu::item { min-height: 36px; padding: 4px 20px; }
QMenu::item:selected { background: #233A2E; color: #F1E9DA; }
QMenu::item:disabled { color: #6C6555; }
QScrollBar:vertical { background: #1B1D1B; width: 16px; margin: 0; }
QScrollBar:horizontal { background: #1B1D1B; height: 16px; margin: 0; }
QScrollBar::handle { background: #788D80; border-radius: 4px; min-width: 24px; min-height: 24px; }
QScrollBar::add-line, QScrollBar::sub-line { width: 0; height: 0; }
QFrame#topBar, QFrame#globalSidebar, QFrame#moduleSidebar { background: #252825; }
QPushButton[navActive="true"] { background: #233A2E; border-left: 3px solid #5AA377; }
QLabel[role="notificationBadge"] { color: #182420; background: #E0716D; border-radius: 8px; padding: 2px 5px; }

QFrame#brandSwatch[brandColor="green"] { background: #18372B; border-radius: 4px; }
QFrame#brandSwatch[brandColor="white"] { background: #FFFFFF; border-radius: 4px; }
QFrame#brandSwatch[brandColor="gold"] { background: #C6A15B; border-radius: 4px; }
QFrame#brandSwatch[brandColor="red"] { background: #9D2927; border-radius: 4px; }
QFrame#brandSwatch[brandColor="charcoal"] { background: #252825; border-radius: 4px; }
QFrame#brandSwatch[brandColor="warm_white"] { background: #F8F8F5; border-radius: 4px; }

