QTabBar::tab:disabled { color: #9C8F7B; }
QMenu { background: #FFFFFF; border: 1px solid #DAD0C1; padding: 4px; }
QMenu::item { min-height: 44px; padding: 4px 20px; }
QMenu::item:selected { background: #DADFDD; color: #252825; }
QMenu::item:disabled { color: #9C8F7B; }
QScrollBar:vertical { background: #F9F9F6; width: 16px; margin: 0; }
QScrollBar:horizontal { background: #F9F9F6; height: 16px; margin: 0; }
QScrollBar::handle { background: #8A7A5C; border-radius: 4px; min-width: 24px; min-height: 24px; }
QScrollBar::add-line, QScrollBar::sub-line { width: 0; height: 0; }
QFrame#topBar, QFrame#globalSidebar, QFrame#moduleSidebar { background: #FFFFFF; }
QPushButton[navActive="true"] { background: #DADFDD; border-left: 3px solid #18372B; }
QLabel[role="notificationBadge"] { color: #FFFFFF; background: #9D2927; border-radius: 8px; padding: 2px 5px; }

QFrame#brandSwatch[brandColor="green"] { background: #18372B; border-radius: 4px; }
QFrame#brandSwatch[brandColor="white"] { background: #FFFFFF; border-radius: 4px; }
QFrame#brandSwatch[brandColor="gold"] { background: #C6A15B; border-radius: 4px; }
QFrame#brandSwatch[brandColor="red"] { background: #9D2927; border-radius: 4px; }
QFrame#brandSwatch[brandColor="charcoal"] { background: #252825; border-radius: 4px; }
QFrame#brandSwatch[brandColor="warm_white"] { background: #F8F8F5; border-radius: 4px; }
